use product_source_ingestion::row_delta::{project,batch};use serde_json::{json};use std::time::Instant;
fn main(){let mut full=json!({"subscription":"s","query_generation":1,"sequence":1,"start_rank":0,"version":1,"total_rows":120,"rows":(0..100).map(|i|json!({"id":format!("r{i:03}"),"category":"a","quantity":"9223372036854775807","amount":{"coefficient":i.to_string(),"scale":0},"label":{"state":"value","value":format!("日本語🦀-{}",i)}})).collect::<Vec<_>>()});full["rows"]=json!(full["rows"].as_array().unwrap().iter().map(|v|serde_json::to_value(serde_json::from_value::<rust_differential_product_core::product::ProductRow>(v.clone()).unwrap()).unwrap()).collect::<Vec<_>>());let projection=vec!["label".into(),"quantity".into()];let projected=project(&full,&projection);let(_,base)=batch(None,1,&projection,projected.clone(),false);
 for case in ["sparse","reorder","boundary","dense"]{let mut target=full.clone();match case{"sparse"=>target["rows"][43]["label"]["value"]=json!("changed"),"reorder"=>{let r=target["rows"].as_array_mut().unwrap().remove(99);target["rows"].as_array_mut().unwrap().insert(0,r);},"boundary"=>{target["rows"].as_array_mut().unwrap().pop();let mut r=full["rows"][0].clone();r["id"]=json!("entry");r["label"]["value"]=json!("entry");target["rows"].as_array_mut().unwrap().insert(0,r);target["total_rows"]=json!(121);},"dense"=>for r in target["rows"].as_array_mut().unwrap(){r["label"]["value"]=json!("dense change");},_=>unreachable!()};target["version"]=json!(2);let next=project(&target,&projection);
 for repetition in (0..3).filter(|r|std::env::var("ROW_MEASURE_REPETITION").ok().is_none_or(|v|v==r.to_string())){for iteration in 0..110{let order=if (repetition+iteration)%2==0{["accepted_full_window","projected_snapshot","projected_delta"]}else{["projected_delta","projected_snapshot","accepted_full_window"]};for mode in order{let started=Instant::now();let(frame,kind,payloads,diff_ns)=if mode=="accepted_full_window"{(target.clone(),"historical_full_window",100,0)}else{let diff_start=Instant::now();let(f,_)=batch(Some(&base),1,&projection,next.clone(),mode=="projected_snapshot");let diff_ns=diff_start.elapsed().as_nanos();let kind=if f["kind"]=="snapshot"{"snapshot"}else{"delta"};let payloads=if kind=="snapshot"{100}else{f["operations"].as_array().unwrap().iter().filter(|o|o.get("row").is_some()).count()};(f,kind,payloads,diff_ns)};let envelope=json!({"type":"result","v":if mode=="accepted_full_window"{13}else{14},"incarnation":"a".repeat(32),"connection":"1","nonce":"b".repeat(32),"subscription":"s","acquisition":1,"source_sequence":"2","result":frame});let prepare_start=Instant::now();let prepared=v13_codec_experiment::prepare(&envelope).unwrap();let prepare_ns=prepare_start.elapsed().as_nanos();let encode_start=Instant::now();let bytes=v13_codec_experiment::encode_mp(&prepared).unwrap();let encode_ns=encode_start.elapsed().as_nanos();let total_ns=started.elapsed().as_nanos();if iteration>=10{println!("{}",json!({"case":case,"repetition":repetition,"iteration":iteration-10,"mode":mode,"decision":kind,"encoded_bytes":bytes.len(),"payload_rows":payloads,"native_window_rows_materialized":100,"projection_rows_materialized":if mode=="accepted_full_window"{0}else{100},"baseline_json_bytes":serde_json::to_vec(&base.result).unwrap().len(),"diff_ns":diff_ns,"prepare_ns":prepare_ns,"encode_ns":encode_ns,"total_ns":total_ns}));}}}}
 }
}
